body.script:
(async function(){
  const frame=document.getElementById('fusion-embed-frame');
  const base=new URL('./',location.href).href;
  const p=new URLSearchParams(location.search);
  const target=p.get('target')||'';
  const wisp=p.get('wisp')||'wss://anura.pro/wisp/';
  const transport=p.get('transport')||'libcurl';
  const send=data=>{try{window.parent.postMessage({type:'fusion-embed',...data},'*')}catch{}};
  try{
    if(!target)throw new Error('No target URL supplied.');

    // Do NOT register the Service Worker from embed.svg. The embedded
    // runtime must initialize Bare-Mux first so the SW can obtain a
    // valid SharedWorker MessagePort as soon as it starts.
    const params=new URLSearchParams({target,wisp,transport,v:String(Date.now())});
    frame.onload=()=>send({status:'runtime-loaded'});
    frame.onerror=()=>send({status:'error',detail:'Failed to load FUSION runtime.html'});
    frame.src=base+'runtime.html?'+params.toString();
  }catch(error){
    console.error('[FUSION EMBED BOOT]',error);
    send({status:'error',detail:error?.message||String(error)});
  }
})();
